import{c as t,Q as o,j as n,m as a}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"SportIdent USB stations on macOS","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/sportident-usb-on-macos.md","filePath":"user/reference/sportident-usb-on-macos.md"}'),s={name:"user/reference/sportident-usb-on-macos.md"};function r(i,e,l,h,d,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="sportident-usb-stations-on-macos" tabindex="-1">SportIdent USB stations on macOS <a class="header-anchor" href="#sportident-usb-stations-on-macos" aria-label="Permalink to &quot;SportIdent USB stations on macOS&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators using a SportIdent USB station on a Mac.</p><p>On macOS, a SportIdent USB station needs a driver from Silicon Labs before the browser can see it at all. This page covers the symptom, why it happens, how to install the driver, and the one step in that installer that looks like a failure but isn&#39;t.</p><blockquote><p><strong>Applies to:</strong> SportIdent&#39;s USB reader stations — the <strong>BSM7-USB</strong> and <strong>BSM8-USB</strong> (SportIdent call the BSM8-USB the <em>mini Reader</em>) — on <strong>macOS</strong>, in any browser that can use Web Serial (<strong>Chrome</strong>, <strong>Edge</strong> or <strong>Firefox 151+</strong>). The missing driver is a macOS problem, not a browser one, so changing browser doesn&#39;t help. It&#39;s the same reader whether you&#39;re downloading cards or reading a control&#39;s backup memory. Windows and Linux are unaffected — see <a href="#do-windows-and-linux-need-this">Do Windows and Linux need this?</a> below.</p></blockquote><blockquote><p><strong>Note — control stations (BSF8, BSF9) aren&#39;t affected.</strong> A station you put out in the forest has no USB connection to the Mac. You read and program it <em>through</em> the USB reader, sat on the reader or coupled to it — so the driver is about the reader on your desk, not the units on your course.</p></blockquote><h2 id="the-symptom" tabindex="-1">The symptom <a class="header-anchor" href="#the-symptom" aria-label="Permalink to &quot;The symptom&quot;">​</a></h2><p>The station is plugged in and powered, but it never appears in the browser&#39;s serial-port chooser when you click <strong>Select Device</strong> on the <strong>Download Card</strong> page. The chooser is empty, or lists only unrelated ports.</p><h2 id="why-it-happens" tabindex="-1">Why it happens <a class="header-anchor" href="#why-it-happens" aria-label="Permalink to &quot;Why it happens&quot;">​</a></h2><p>SportIdent&#39;s USB stations use a <strong>Silicon Labs CP210x</strong> USB-to-UART bridge chip, but they identify themselves with SportIdent&#39;s own USB product ID (<code>10C4:800A</code>) rather than the standard Silicon Labs one. The CP210x driver built into macOS only recognises the standard Silicon Labs IDs, so it never attaches to the station and <strong>no serial port (<code>/dev/cu.*</code>) is created for it</strong>.</p><p>The bridge chip is what matters here, not the model number: SportIdent use the same CP210x family across their USB stations and USB accessories, so the fix below is the same whichever one you plug in.</p><p>Web Serial can only offer up real serial ports. With no driver attached there is no port, so the station is invisible to the browser — even though it does show up as a USB device in <strong>System Information</strong>.</p><h2 id="install-the-silicon-labs-cp210x-driver" tabindex="-1">Install the Silicon Labs CP210x driver <a class="header-anchor" href="#install-the-silicon-labs-cp210x-driver" aria-label="Permalink to &quot;Install the Silicon Labs CP210x driver&quot;">​</a></h2><ol><li>Download the <strong>CP210x VCP Driver for macOS</strong> from Silicon Labs: <a href="https://www.silabs.com/software-and-tools/usb-to-uart-bridge-vcp-drivers" target="_blank" rel="noreferrer">https://www.silabs.com/software-and-tools/usb-to-uart-bridge-vcp-drivers</a>. (Verified working with driver <strong>v6.0.3</strong>, which includes the SportIdent product ID.)</li><li>Open the downloaded installer and follow its steps.</li></ol><h3 id="the-installer-will-appear-to-hang-—-this-is-expected" tabindex="-1">The installer will appear to hang — this is expected <a class="header-anchor" href="#the-installer-will-appear-to-hang-—-this-is-expected" aria-label="Permalink to &quot;The installer will appear to hang — this is expected&quot;">​</a></h3><p>At the <strong>Installing new driver…</strong> step the progress bar stops and never completes. <strong>The installer is not stuck.</strong> It is waiting for you to approve the driver in macOS System Settings, and macOS often shows no prompt asking you to do it. Re-running the installer doesn&#39;t help.</p><p>To approve the driver:</p><ol><li>Open <strong>System Settings → General → Login Items &amp; Extensions</strong>.</li><li>Scroll <strong>past</strong> the &quot;Allow in the Background&quot; list to the <strong>Extensions</strong> section.</li><li>Find <strong>Driver Extensions</strong> and click its <strong>ⓘ</strong> (info) button.</li><li>In the sheet that opens, switch on <strong>CP210x VCP Driver</strong> (<code>com.silabs.cp210x</code>) and authenticate with your password.</li><li>The installer window then continues past &quot;Installing new driver…&quot; on its own.</li></ol><blockquote><p><strong>Warning:</strong> A <strong>Silicon Laboratories Inc</strong> toggle may appear in the <strong>Allow in the Background</strong> list. That is <em>not</em> the driver approval — keep scrolling to <strong>Extensions</strong>.</p></blockquote><blockquote><p><strong>Tip:</strong> If you already force-quit the installer, that&#39;s fine. The approval is the part that matters; there&#39;s no need to run the installer again.</p></blockquote><p>If there&#39;s no <strong>Driver Extensions</strong> entry, or the sheet is empty, <strong>reboot</strong> — the pending approval survives a restart and the toggle will be there afterwards.</p><p>On <strong>macOS Sequoia and earlier</strong>, the approval lives in <strong>System Settings → Privacy &amp; Security</strong> instead, as an <strong>Allow</strong> button near the bottom.</p><h2 id="check-it-worked" tabindex="-1">Check it worked <a class="header-anchor" href="#check-it-worked" aria-label="Permalink to &quot;Check it worked&quot;">​</a></h2><ol><li><p>Unplug and replug the station.</p></li><li><p>A new serial port named <code>/dev/cu.SLAB_USBtoUART</code> should now exist. To confirm, open <strong>Terminal</strong> and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/cu.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span></code></pre></div></li><li><p>Back in the browser, click <strong>Select Device</strong> again. The chooser now lists the station — shown as <strong>CP210x USB to UART Bridge Controller</strong> / <code>cu.SLAB_USBtoUART</code>. Select it, and downloads work normally from then on.</p></li></ol><p>The driver install and its approval are a <strong>one-time setup per Mac</strong>. New stations plugged into the same Mac are picked up without repeating any of it.</p><h2 id="do-windows-and-linux-need-this" tabindex="-1">Do Windows and Linux need this? <a class="header-anchor" href="#do-windows-and-linux-need-this" aria-label="Permalink to &quot;Do Windows and Linux need this?&quot;">​</a></h2><p>No.</p><ul><li><strong>Windows</strong> — SportIdent supply a driver for their stations; install that and the station appears as a COM port.</li><li><strong>Linux</strong> — this product ID is supported out of the box; the station appears as <code>/dev/ttyUSB*</code> with nothing to install.</li></ul><p>Only macOS needs the manual driver install described above.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../running-the-event/card-download">Downloading cards</a> — connecting the reader and the download flow it feeds.</li><li><a href="./../running-the-event/station-memory">Station Memory</a> — reading a control unit&#39;s backup memory through a USB master station.</li><li><a href="./https-and-certificates">HTTPS and certificates</a> — the <em>other</em> reason the reader controls may not appear: Web Serial needs a secure connection off the server machine.</li><li><a href="./sportident-cards">SportIdent cards</a> — card types and what Manager reads from them.</li><li><a href="./../download-and-install/">Download, install and update</a> — installing Manager itself on macOS.</li><li><a href="./troubleshooting">Troubleshooting</a> — general &quot;it won&#39;t start / won&#39;t connect&quot; help.</li></ul>',30)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
